export default function App() {
  const locale = useWidgetLocale(),
    client = useQueryClient();
  const mail = useMemo(() => createMailbox(client), [client]);
  useEffect(() => {
    const dispose = registerInterfaces(mail);
    return () => dispose.forEach((fn) => fn());
  }, [mail, locale]);
  useEffect(
    () =>
      pudding.storage.subscribe(() => {
        void client.invalidateQueries({ queryKey: ["gmail-board-view"] });
      }),
    [client],
  );
  const profile = useQuery({
    queryKey: ["gmail-board-view", "account"],
    queryFn: () => mail.profile(),
    retry: false,
  });
  const account = profile.data;
  const [search, setSearch] = useState("in:inbox"),
    [q, setQ] = useState("in:inbox"),
    [cursors, setCursors] = useState([""]),
    [selected, setSelected] = useState<string | null>(null),
    [status, setStatus] = useState<Card["status"]>("todo"),
    [refreshing, setRefreshing] = useState(false),
    [error, setError] = useState<unknown>(null);
  const cursor = cursors[cursors.length - 1];
  const list = useQuery({
    queryKey: ["gmail-board-view", "list", account, q, cursor],
    queryFn: ({ signal }) => mail.list(account!, q, cursor, 20, signal),
    enabled: !!account,
    retry: false,
  });
  const isTodoTab = status === "todo";
  const taggedList = list.data?.taggedCards ?? [];
  const items = isTodoTab
    ? (list.data?.items.filter((item) => item.status === "todo") ?? [])
    : taggedList.filter((item) => item.status === status);

  const tabCounts = useMemo(() => {
    const todoCount =
      list.data?.items.filter((item) => item.status === "todo").length ?? 0;
    const tagged = list.data?.taggedCards ?? [];
    return {
      todo: todoCount,
      reply: tagged.filter((c) => c.status === "reply").length,
      followUp: tagged.filter((c) => c.status === "followUp").length,
      done: tagged.filter((c) => c.status === "done").length,
    };
  }, [list.data]);
  function find() {
    setQ(search.trim());
    setCursors([""]);
    setSelected(null);
  }
  async function refresh() {
    if (!account) return;
    setRefreshing(true);
    setError(null);
    try {
      await mail.refresh(account);
      await client.invalidateQueries({ queryKey: ["gmail-board-view"] });
    } catch (e) {
      setError(e);
    } finally {
      setRefreshing(false);
    }
  }
  return (
    <main className="gb-app">
      <header className="gb-header">
        <div className="gb-brand">
          <span className="gb-icon" aria-hidden="true" />
          <div>
