  align-items: center;
  gap: 8px;
  padding: 3px 4px 3px 10px;
  border: 1px solid var(--edge);
  border-radius: 8px;
  flex: 0 1 460px;
  min-width: 160px;
}
.gb-search input {
  width: 0;
  min-width: 0;
  flex: 1;
  border: 0;
  background: transparent;
  padding: 5px;
  outline: 0;
  font-size: 13px;
}
.gb-search button {
  padding: 5px 9px;
  font-size: 12px;
}
.gb-help {
  position: relative;
  flex-shrink: 0;
  color: var(--muted);
}
.gb-help > summary {
  list-style: none;
  cursor: pointer;
  display: grid;
  place-items: center;
  width: 30px;
  height: 34px;
  border-radius: 6px;
}
.gb-help > summary::-webkit-details-marker {
  display: none;
}
.gb-help > div {
  position: absolute;
  top: 42px;
  right: 0;
  width: 280px;
  z-index: 3;
  padding: 14px;
  background: var(--surface);
  border: 1px solid var(--edge);
  border-radius: 9px;
  box-shadow: 0 8px 24px #0002;
  font-size: 12px;
}
.gb-help p {
  margin-top: 8px;
}
.gb-app .gb-refresh {
  width: 34px;
  height: 34px;
  padding: 7px;
}
.gb-page-info {
  padding: 0 12px;
  border-top: 1px solid var(--edge);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  height: 44px;
  flex-shrink: 0;
  color: var(--muted);
  font-size: 12px;
}
.gb-pager {
  display: flex;
  align-items: center;
  gap: 10px;
}
.gb-pager button {
  padding: 4px 6px;
}
.gb-workspace {
  min-height: 0;
  min-width: 0;
  flex: 1;
  display: grid;
  grid-template-columns: minmax(300px, 34%) minmax(320px, 1fr);
  margin-top: 16px;
  overflow: auto;
  border: 1px solid var(--edge);
  border-radius: 10px;
}
.gb-inbox {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  border-right: 1px solid var(--edge);
}
.gb-status-tabs {
  display: flex;
  flex-shrink: 0;
  border-bottom: 1px solid var(--edge);
  padding: 0 10px;
  gap: 6px;
  overflow-x: auto;
}
.gb-status-tabs button {
  flex: 1;
  padding: 14px 5px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--muted);
  font-size: 12px;
  gap: 4px;
}
.gb-status-tabs button[aria-selected="true"] {
  color: var(--text);
  box-shadow: inset 0 -2px var(--text);
}
.gb-status-tabs button > span {
  font-size: 10px;
  color: var(--muted);
}
.gb-cards {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.gb-reader-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 24px;
  color: var(--muted);
  font-size: 13px;
  text-align: center;
}
.gb-app .gb-card {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  text-align: left;
  white-space: normal;
  gap: 7px;
  min-width: 0;
  padding: 15px 16px;
  border: 0;
  border-bottom: 1px solid var(--edge);
  border-radius: 0;
}
.gb-card[aria-pressed="true"] {
  background: var(--panel);
  box-shadow: inset 3px 0 var(--text);
}
.gb-card-top {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--muted);
}
.gb-card-top > span {
  flex: 1;
  min-width: 0;
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: nowrap;
}
.gb-card-top i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--text);
  flex-shrink: 0;
}
.gb-card > strong {
  font-size: 13px;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  overflow-wrap: anywhere;
}
.gb-card > p {
  font-size: 12px;
  color: var(--muted);
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  overflow-wrap: anywhere;
}
.gb-card footer {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  color: var(--muted);
  font-size: 10px;
  gap: 5px;
  margin-top: 3px;
}
.gb-empty {
  padding: 24px 10px;
  color: var(--muted);
  text-align: center;
  font-size: 12px;
}
.gb-detail {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  background: var(--surface);
  color: var(--text);
  overflow: hidden;
}
.gb-detail-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 24px 10px;
  flex-shrink: 0;
}
.gb-detail-top > span {
  font-size: 12px;
  color: var(--muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gb-detail-top button {
  padding: 5px;
  border-color: transparent;
}
.gb-detail-tabs {
  display: flex;
  gap: 18px;
  padding: 0 24px;
  border-bottom: 1px solid var(--edge);
  flex-shrink: 0;
}
.gb-detail-tabs button {
  border: 0;
  background: transparent;
  border-radius: 0;
  padding: 12px 0;
  color: var(--muted);
  font-size: 13px;
}
.gb-detail-tabs button[aria-pressed="true"] {
  color: var(--text);
  box-shadow: 0 2px 0 var(--text);
}
.gb-detail-tabs i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--muted);
}
.gb-detail-scroll {
  flex: 1;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  padding: 24px;
  scrollbar-gutter: stable;
}
.gb-thread-title {
  margin-bottom: 12px !important;
}
.gb-messages {
  display: flex;
  flex-direction: column;
  gap: 22px;
  margin: 24px 0;
}
.gb-messages article {
  min-width: 0;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--edge);
}
.gb-message-card {
  padding-bottom: 22px;
  border-bottom: 1px solid var(--edge);
}
.gb-message-card-header {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}
.gb-sender-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--panel);
  border: 1px solid var(--edge);
  color: var(--text);
  font-weight: 600;
  font-size: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  user-select: none;
}
.gb-message-header-info {
  flex: 1;
  min-width: 0;
}
.gb-sender-line {
  display: flex;
  align-items: baseline;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
}
.gb-sender-name {
  font-size: 13px;
  color: var(--text);
  font-weight: 600;
}
.gb-sender-email {
  font-size: 11px;
  color: var(--muted);
  font-weight: normal;
}
.gb-message-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 12px;
  align-items: center;
  justify-content: space-between;
}
.gb-message-meta time,
.gb-recipient {
  font-size: 11px;
  color: var(--muted);
}
.gb-recipient {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-top: 3px !important;
}
.gb-view-toggle {
  display: inline-flex;
  background: var(--panel);
  border: 1px solid var(--edge);
  border-radius: 6px;
  padding: 2px;
  gap: 2px;
  flex-shrink: 0;
}
.gb-view-toggle button {
  border: none;
  background: transparent;
  padding: 3px 7px;
  border-radius: 4px;
  font-size: 11px;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  line-height: 1;
}
.gb-view-toggle button:hover {
  color: var(--text);
}
.gb-view-toggle button.is-active {
  background: var(--bg);
  color: var(--text);
  font-weight: 500;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}
.gb-message-content {
  margin-top: 14px;
}
.gb-plain-body {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  font-family: inherit;
  font-size: 14px;
  line-height: 1.65;
  color: var(--text);
}
.gb-link-chip {
  display: inline-flex;
  align-items: center;
  vertical-align: middle;
  margin: 1px 3px;
  padding: 2px 7px;
  border-radius: 4px;
  background: var(--panel);
  border: 1px solid var(--edge);
  font-size: 12px;
  line-height: 1.4;
  gap: 5px;
  max-width: 100%;
}
.gb-link-url {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: #3b82f6;
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gb-link-url:hover {
  text-decoration: underline;
}
.gb-link-copy-btn {
  border: none;
  background: transparent;
  padding: 2px;
  border-radius: 3px;
  color: var(--muted);
  cursor: pointer;
  display: flex;
  align-items: center;
}
.gb-link-copy-btn:hover {
  color: var(--text);
  background: rgba(127, 127, 127, 0.15);
}
.gb-email-html {
  font-size: 14px;
  line-height: 1.6;
  color: var(--text);
  overflow-x: auto;
  max-width: 100%;
  word-break: break-word;
}
.gb-email-html img {
  max-width: 100% !important;
  height: auto !important;
}
.gb-email-html table {
  max-width: 100% !important;
}
.gb-email-html a {
  color: #3b82f6;
  text-decoration: underline;
}
.gb-truncated {
  margin-top: 8px;
}
.gb-form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.gb-form label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  font-size: 12px;
  min-width: 0;
}
.gb-form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.gb-form :is(input, select, textarea) {
  width: 100%;
  min-width: 0;
  padding: 9px 11px;
  border: 1px solid var(--edge);
  border-radius: 7px;
  background: var(--surface);
  font-size: 14px;
}
.gb-form textarea {
  resize: vertical;
  line-height: 1.6;
}
.gb-save {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 40px;
  position: sticky;
  bottom: -24px;
  background: var(--surface);
  padding: 12px 0;
  border-top: 1px solid var(--edge);
}
.gb-save span {
  font-size: 11px;
  color: var(--muted);
}
.gb-app .gb-primary {
  background: var(--action);
  color: var(--on-action);
}
.gb-alert {
  position: absolute;
  right: 20px;
  top: 64px;
  z-index: 4;
  width: min(460px, calc(100% - 40px));
  box-shadow: 0 4px 20px #0002;
  border-radius: 8px;
}
.gb-error {
  max-width: 100%;
  border: 1px solid light-dark(#dfbaba, #704444);
  background: var(--surface);
  padding: 10px 12px;
  border-radius: 8px;
  font-size: 12px;
  overflow: hidden;
}
.gb-detail .gb-error {
  margin-bottom: 12px;
}
.gb-error > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.gb-error > div > strong {
  font-weight: 500;
}
.gb-error button {
  padding: 4px 8px;
  font-size: 12px;
}
.gb-error summary {
  cursor: pointer;
  padding: 5px 0 0;
  color: var(--muted);
}
.gb-error textarea {
  margin-top: 10px;
  width: 100%;
  height: 132px;
  max-height: 160px;
  resize: none;
  font:
    12px/1.6 ui-monospace,
    monospace;
  color: var(--text);
  border: 1px solid var(--edge);
  border-radius: 5px;
  background: var(--panel);
  padding: 8px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.gb-copy-row {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-top: 8px;
}
.gb-copy-row span {
  font-size: 11px;
  color: var(--muted);
}
.gb-spin {
  animation: gb-spin 1.5s linear infinite;
}
@keyframes gb-spin {
  to {
    transform: rotate(360deg);
  }
}
@media (max-width: 740px) {
  .gb-app {
    padding: 12px;
  }
  .gb-header {
    flex-wrap: wrap;
    gap: 10px;
  }
  .gb-brand {
    flex: 1;
    min-width: 0;
  }
  .gb-search {
    order: 4;
    flex: 1 1 100%;
    min-width: 0;
  }
  .gb-account {
    max-width: 190px;
  }
  .gb-workspace {
    grid-template-columns: 280px minmax(320px, 1fr);
    margin-top: 12px;
  }
  .gb-detail-scroll {
    padding: 20px;
  }
  .gb-detail-top {
    padding: 12px 20px 8px;
  }
  .gb-detail-tabs {
    padding: 0 20px;
  }
  .gb-alert {
    right: 12px;
    top: 108px;
    width: calc(100% - 24px);
  }
}
